import socket
import json
import time
import math
import numpy as np

# Load target profile generated by MONAI pipeline
try:
    with open("clinical_target_profile.json", "r") as f:
        profile = json.load(f)
    print(f" Loaded Clinical Target Profile for {profile['patient_id']}")
    TUMOR_TARGET = np.array(profile["lesion_centroid_lps_mm"])
    SAFETY_MARGIN = profile["recommended_margin_clearance_mm"]
    CRITICAL_MARGIN = profile["critical_margin_threshold_mm"]
except FileNotFoundError:
    TUMOR_TARGET = np.array([0.0, 0.0, 0.0])
    SAFETY_MARGIN = 10.0
    CRITICAL_MARGIN = 3.5

BROADCAST_IP = "255.255.255.255"
PORT = 18944

sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)

print("=" * 65)
print(" SURGIVISION™ CLINICAL TELEMETRY BROADCASTER - ACTIVE")
print(f" Mode: Subnet Broadcast | Port: {PORT}")
print(f" Target Lesion Centroid (LPS): {TUMOR_TARGET} mm")
print("=" * 65)

t = 0.0
try:
    while True:
        tremor = np.random.normal(0, 0.1, 3)
        pos_x = TUMOR_TARGET[0] + 16.0 * math.sin(t * 0.45) + tremor[0]
        pos_y = TUMOR_TARGET[1] + 10.0 * math.cos(t * 0.35) + tremor[1]
        pos_z = TUMOR_TARGET[2] + 18.0 * math.cos(t * 0.45) + tremor[2]
        
        current_pos = np.array([pos_x, pos_y, pos_z])
        margin_mm = float(np.linalg.norm(current_pos - TUMOR_TARGET))

        haptic_force_n = 0.0
        alarm_level = "NOMINAL"

        if margin_mm < CRITICAL_MARGIN:
            alarm_level = "CRITICAL_PERFORATION_RISK"
            haptic_force_n = round(min(18.0, 3.5 + (CRITICAL_MARGIN - margin_mm) * 4.0), 2)
        elif margin_mm < SAFETY_MARGIN:
            alarm_level = "WARNING_MARGIN_PROXIMITY"
            haptic_force_n = round((SAFETY_MARGIN - margin_mm) * 0.7, 2)

        packet = {
            "timestamp_ms": int(time.time() * 1000),
            "frame_id": "TOOL_TIP_POINTER",
            "coords_lps_mm": {
                "x": round(pos_x, 2),
                "y": round(pos_y, 2),
                "z": round(pos_z, 2)
            },
            "margin_clearance_mm": round(margin_mm, 2),
            "haptic_force_n": haptic_force_n,
            "system_state": alarm_level
        }

        sock.sendto(json.dumps(packet).encode("utf-8"), (BROADCAST_IP, PORT))
        print(f"[{alarm_level:<26}] Pos: ({pos_x:5.1f}, {pos_y:5.1f}, {pos_z:5.1f}) mm | Margin: {margin_mm:5.2f} mm", end="\r")

        t += 0.04
        time.sleep(0.033)
except KeyboardInterrupt:
    print("\n Broadcast stopped.")
